const { chromium } = require('playwright')
const path = require('path')

;(async () => {
  const browser = await chromium.launch()
  const page = await browser.newPage({ viewport: { width: 1100, height: 900 } })
  const file = 'file:///' + path.resolve(__dirname, '_harness.html').replace(/\\/g, '/')

  // 修复后
  await page.goto(file)
  await page.waitForTimeout(300)
  await page.screenshot({ path: path.join(__dirname, '_after.png'), fullPage: true })
  const after = await page.evaluate(() => {
    const stack = document.querySelector('.presale-detail-section-stack')
    const row = document.querySelector('.detail-from-container')
    const form = document.querySelector('.zs-form')
    const r = stack.getBoundingClientRect()
    return { stackWidth: r.width, formWidth: form.getBoundingClientRect().width, rowWidth: row.getBoundingClientRect().width, formDir: getComputedStyle(form).flexDirection }
  })
  console.log('AFTER', JSON.stringify(after))

  // 修复前（不加载修复 chunk）
  await page.goto(file + '?nofix')
  await page.waitForTimeout(300)
  await page.screenshot({ path: path.join(__dirname, '_before.png'), fullPage: true })
  const before = await page.evaluate(() => {
    const stack = document.querySelector('.presale-detail-section-stack')
    const form = document.querySelector('.zs-form')
    const r = stack.getBoundingClientRect()
    return { stackWidth: r.width, formWidth: form.getBoundingClientRect().width, formDir: getComputedStyle(form).flexDirection }
  })
  console.log('BEFORE', JSON.stringify(before))

  await browser.close()
})()

